html:
{% set company_doc = frappe.db.get_value("Company", doc.company, ["company_logo", "email", "phone_no"], as_dict=1) if doc.company else {} %}
{% set manufacturer_name = frappe.db.get_value("Supplier", doc.factory, "supplier_name") if doc.factory else "" %}
{% set dealer_name = frappe.db.get_value("Customer", doc.customer, "customer_name") if doc.customer else "" %}

{# Linked records #}
{% set park = frappe.get_doc("Park", doc.park) if doc.park else None %}
{% set buyer = frappe.get_doc("Customer", doc.home_buyer) if doc.home_buyer else None %}
{% set escrow_name = frappe.db.get_value("Supplier", doc.escrow_company, "supplier_name") if doc.escrow_company else "" %}
{% set escrow_phone_default = frappe.db.get_value("Supplier", doc.escrow_company, "supplier_primary_phone") if doc.escrow_company else "" %}

{# Dynamic title based on variant #}
{%- if doc.home_type == "Spec" -%}
  {%- set sheet_title = "Spec New Home Info Sheet" -%}
{%- elif doc.home_type == "Customer Sold" and doc.financing_type == "Cash" and doc.property_type == "Private Property" -%}
  {%- set sheet_title = "Cash Private New Home Info Sheet" -%}
{%- elif doc.home_type == "Customer Sold" -%}
  {%- set sheet_title = "Retail Sold New Home Info Sheet" -%}
{%- else -%}
  {%- set sheet_title = "New Home Info Form" -%}
{%- endif -%}

{%- macro format_currency(amount) -%}
{{ frappe.utils.fmt_money(amount, currency="USD") }}
{%- endmacro -%}

{%- macro fmt_date(d) -%}
{%- if d -%}{{ frappe.utils.formatdate(d, "MM/dd/yyyy") }}{%- endif -%}
{%- endmacro -%}

{%- macro format_phone(phone) -%}
{%- if phone -%}
{%- set digits = phone | replace("+", "") | replace("-", "") | replace(" ", "") | replace("(", "") | replace(")", "") -%}
{%- if digits | length == 10 -%}
+1 ({{ digits[:3] }}) {{ digits[3:6] }}-{{ digits[6:] }}
{%- elif digits | length == 11 and digits[0] == '1' -%}
+1 ({{ digits[1:4] }}) {{ digits[4:7] }}-{{ digits[7:] }}
{%- else -%}
{{ phone }}
{%- endif -%}
{%- endif -%}
{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
  .inv {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
    font-weight: 500 !important;
    color: #000 !important;
    font-size: 13px !important;
    line-height: 1.2 !important;
    width: 100% !important;
  }
  .inv table { border-collapse: collapse !important; width: 100% !important; }
  .inv td, .inv th { padding: 0 !important; vertical-align: top !important; }
  .inv-div {
    border-top: 1px solid #ddd !important; border-bottom: none !important;
    border-left: none !important; border-right: none !important;
    height: 0 !important; margin: 32px 0 !important; background: none !important;
  }
  .lbl { font-weight: 600 !important; font-size: 13px !important; color: #000 !important; padding-bottom: 6px !important; }
  .val { font-size: 13px !important; font-weight: 500 !important; color: #333b44 !important; line-height: 1.4 !important; }

  /* ── Field rows ── */
  .inv-items {
    width: 100% !important; border-collapse: separate !important; border-spacing: 0 !important;
    border-radius: 4px !important; overflow: hidden !important;
  }
  .inv-items thead { display: table-header-group !important; }
  .inv-items thead tr th:first-child { border-top-left-radius: 4px !important; }
  .inv-items thead tr th:last-child { border-top-right-radius: 4px !important; }
  .inv-items thead tr { break-inside: avoid !important; }
  @media print { .inv-items thead { display: table-row-group !important; } }
  .inv-items thead th {
    background: #000 !important; color: #fff !important; font-weight: 600 !important;
    font-size: 12px !important; padding: 12px 20px !important; text-align: left !important;
    letter-spacing: 0.3px !important; border: none !important;
  }
  .inv-items tbody td {
    padding: 12px 20px !important; font-size: 12px !important; font-weight: 500 !important;
    color: #333b44 !important; border-top: none !important; border-left: none !important;
    border-right: none !important; border-bottom: 1px solid #e0e0e0 !important;
    vertical-align: top !important; background: #f5f5f5 !important;
  }
  .inv-items tbody td.f-lbl {
    font-weight: 700 !important; color: #000 !important; width: 260px !important;
  }
  .inv-items tbody td.f-val {
    font-weight: 500 !important; color: #000 !important;
  }
  .inv-items tbody tr:last-child td { border-bottom: none !important; }
  .inv-items tbody tr:last-child td:first-child { border-bottom-left-radius: 4px !important; }
  .inv-items tbody tr:last-child td:last-child { border-bottom-right-radius: 4px !important; }

  /* ── Signature ── */
  .sig-line {
    border-bottom: 1px solid #333 !important;
    min-width: 250px !important;
    display: inline-block !important;
    margin-left: 8px !important;
  }

  .no-break { page-break-inside: avoid !important; }
</style>

<div class="inv">

  <!-- ═══ HEADER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important;">
        <img src="/files/logo.png" style="height: 40px !important; object-fit: contain !important; display: block !important;" alt="Dealer Capital Resources">
      </td>
      <td style="width: 50% !important; text-align: right !important;">
        <div style="font-size: 13px !important; color: #333b44 !important;">{{ doc.name }}</div>
      </td>
    </tr>
  </table>

  <div class="inv-div"></div>

  <!-- ═══ TITLE ═══ -->
  <div style="font-size: 20px !important; font-weight: 600 !important; color: #000 !important; padding-bottom: 8px !important;">{{ sheet_title }}</div>
  <div class="val" style="padding-bottom: 4px !important;">Dealer: {{ dealer_name }}</div>
  <div class="val">Home: {{ doc.home_name or doc.name }}</div>

  <!-- ═══════════════════════════════════════════════════════ -->
  <!-- COMMUNITY INFORMATION — Park variants only             -->
  <!-- ═══════════════════════════════════════════════════════ -->
  {% if doc.property_type == "Park" %}
  <table class="inv-items" style="margin-top: 24px !important;">
    <thead>
      <tr><th colspan="2">Community Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Community Name</td>
        <td class="f-val">{{ park.park_name if park else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Address</td>
        <td class="f-val">{{ park.address_line1 if park else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">City, St Zip</td>
        <td class="f-val">{{ (park.city or '') ~ ', ' ~ (park.state or '') ~ ' ' ~ (park.zip or '') if park else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Gated Community</td>
        <td class="f-val">{{ "Yes" if park and park.gated else "No" }}{% if park and park.access_code %} &nbsp;&nbsp; Access Code: {{ park.access_code }}{% endif %}</td>
      </tr>
      <tr>
        <td class="f-lbl">Space #</td>
        <td class="f-val">{{ doc.space_number or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Office Phone</td>
        <td class="f-val">{{ format_phone(park.office_phone) if park else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Community Contact</td>
        <td class="f-val">{{ park.contact_name if park else '' }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ═══════════════════════════════════════════════════════ -->
  <!-- CUSTOMER INFORMATION — Customer Sold variants only     -->
  <!-- ═══════════════════════════════════════════════════════ -->
  {% if doc.home_type == "Customer Sold" %}
  <table class="inv-items" style="margin-top: 24px !important;">
    <thead>
      <tr><th colspan="2">Customer Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Customer Name</td>
        <td class="f-val">{{ buyer.customer_name if buyer else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Customer Address</td>
        <td class="f-val">{{ buyer.customer_primary_address or '' if buyer else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Customer Phone #</td>
        <td class="f-val">{{ format_phone(buyer.mobile_no or buyer.phone) if buyer else '' }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ═══════════════════════════════════════════════════════ -->
  <!-- ESCROW INFORMATION — Customer Sold variants only       -->
  <!-- ═══════════════════════════════════════════════════════ -->
  {% if doc.home_type == "Customer Sold" %}
  <table class="inv-items" style="margin-top: 16px !important;">
    <thead>
      <tr><th colspan="2">Escrow Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Escrow Company</td>
        <td class="f-val">{{ escrow_name }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Escrow Number</td>
        <td class="f-val">{{ doc.escrow_number or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Escrow Phone #</td>
        <td class="f-val">{{ format_phone(doc.escrow_phone or escrow_phone_default) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Escrow Contact</td>
        <td class="f-val">{{ doc.escrow_contact or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Amount of Customer Deposit in Escrow</td>
        <td class="f-val">{{ format_currency(doc.customer_deposit) if doc.customer_deposit else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Selling Price of Home</td>
        <td class="f-val">{{ format_currency(doc.selling_price) if doc.selling_price else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Lender</td>
        <td class="f-val">{{ doc.end_buyer_lender or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Broker</td>
        <td class="f-val">{{ frappe.db.get_value("Supplier", doc.broker, "supplier_name") if doc.broker else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Broker Contact</td>
        <td class="f-val">{{ doc.broker_contact or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Broker Phone</td>
        <td class="f-val">{{ format_phone(doc.broker_phone) }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ═══════════════════════════════════════════════════════ -->
  <!-- HOME INFORMATION — Always shown                        -->
  <!-- ═══════════════════════════════════════════════════════ -->
  <table class="inv-items" style="margin-top: 16px !important;">
    <thead>
      <tr><th colspan="2">Home Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Manufacturer</td>
        <td class="f-val">{{ manufacturer_name }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Model</td>
        <td class="f-val">{{ doc.model_name or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Home Invoice plus freight</td>
        <td class="f-val">{{ format_currency(doc.home_invoice_plus_freight) if doc.home_invoice_plus_freight else '' }}</td>
      </tr>
    </tbody>
  </table>

  <div class="inv-div"></div>

  <!-- ═══ SIGNATURE ═══ -->
  <div class="no-break">
    <table style="margin-top: 16px !important;">
      <tr>
        <td style="width: 50% !important; padding-top: 24px !important;">
          <div class="lbl">Signed: <span style="color: #fff !important; font-size: 1px !important;">/sig1/</span><span class="sig-line">&nbsp;</span></div>
        </td>
        <td style="width: 50% !important; padding-top: 24px !important;">
          <div class="lbl">Date: <span style="color: #fff !important; font-size: 1px !important;">/ds1/</span><span class="sig-line">&nbsp;</span></div>
        </td>
      </tr>
    </table>
  </div>

  <div class="inv-div"></div>

  <!-- ═══ FOOTER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important; vertical-align: top !important;">
        <img src="/files/Icon.png" style="height: 25px !important; object-fit: contain !important; display: block !important; filter: brightness(0) !important;" alt="DCR">
      </td>
      <td style="width: 50% !important; text-align: right !important; vertical-align: top !important;">
        <div class="lbl">Contact</div>
        <div class="val">{{ company_doc.email or 'accounting@dealercapital.net' }}</div>
        <div class="val">{{ format_phone(company_doc.phone_no or '8004541116') }}</div>
      </td>
    </tr>
  </table>

</div>
